    def handleReturnPressed(self, text):
        try:
            self.lineEdit.clear()
            if text.lower() in self.ChatPlaysProgram.getInputs():
                self.listWidget.addItem(text.lower())
                self.ChatPlaysProgram.addTestQueue(text.lower())     

        except TypeError:
            return

